protected CustTable getCustTable()
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && !custTable)
    {
        if (rebatePosting.DynamicAccount == TAMRebateDynamicAccount::None)
        {
            CustAccount custAccount = this.Recipient ? this.Recipient : LedgerDimensionFacade::getDisplayValueForLedgerDimension(rebatePosting.RebateLedgerDimension);

            custTable = CustTable::find(custAccount);
        }
        else
        {
            custTable = CustTable::find(rebateTable.AccountRelation);
        }
    }

    return next getCustTable();
}
